// Normalize webhook payload (Web Analyzer, manual POST, or CRM form relay).
const raw = $input.item.json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const company = String(body.company || body.organization || body.org || body.domain || '').trim();
const email = String(body.clientEmail || body.client_email || body.email || body.contact_email || '').trim();
const name = String(body.clientName || body.client_name || body.name || body.contact_name || body.contact || '').trim();
const url = String(body.url || body.website || body.page_url || body.pageUrl || '').trim();
const summary = String(body.summary || body.description || body.snippet || body.text || body.content || '').trim();
const orgSlug = String(body.org_slug || body.orgSlug || 'zion').trim().toLowerCase();
const source = String(body.source || body.analyzer || 'web_analyzer').trim();

const answers = {
  source,
  ...(url ? { url } : {}),
  ...(summary ? { summary: summary.slice(0, 4000) } : {}),
};
if (body.signals && typeof body.signals === 'object') Object.assign(answers, body.signals);
if (body.answers && typeof body.answers === 'object') Object.assign(answers, body.answers);
if (body.metadata && typeof body.metadata === 'object') answers.metadata = body.metadata;

const displayName = name || company || (url ? url.replace(/^https?:\/\//, '').split('/')[0] : '') || 'Web lead';
const researchTopic = company || (url ? `Prospect: ${url}` : '') || summary.slice(0, 120);
const researchNotes = [
  source && `Source: ${source}`,
  url && `URL: ${url}`,
  email && `Email: ${email}`,
  summary && summary.slice(0, 800),
].filter(Boolean).join('\n');

return [{
  json: {
    org_slug: orgSlug,
    clientName: displayName,
    clientEmail: email,
    company,
    answers,
    researchTopic,
    researchNotes,
    skipResearch: body.skipResearch === true || !researchTopic,
  },
}];
